		}
		if err := validateLiveSemanticHeader(header, storage.Key, head, tree); err != nil {
			return err
		}
		warnings = append(warnings, header.Warnings...)
	}
	if header.Commit == "" {
		header.Commit = head
	}
	if header.Tree == "" {
