	if err := json.Unmarshal(scanner.Bytes(), &header); err != nil {
		return fmt.Errorf("parse bundle semantic snapshot header: %w", err)
	}
	if header.RepoKey == "" {
		return errors.New("bundle semantic snapshot header missing repo_key")
	}
	if header.RepoKey != repoKey {
		return fmt.Errorf("bundle semantic snapshot repo_key %q does not match current repo %q", header.RepoKey, repoKey)
	}
	if err := validateSemanticSchema(header.SchemaVersion); err != nil {
